  ren->AddVolume(volume); ren->SetBackground(0.3, 0.3, 0.3); ren->ResetCamera();
  vtkNew<vtkRenderWindow> rw;
  rw->SetSize(300, 300); rw->AddRenderer(ren); rw->SetOffScreenRendering(1);
