  vtkNew<vtkWindowToImageFilter> w2i;
  w2i->SetInput(rw); w2i->SetInputBufferTypeToRGB();
  vtkNew<vtkPNGWriter> wr;
  wr->SetInputConnection(w2i->GetOutputPort());
